<?php

namespace Database\Seeders;

use App\Models\Author;
use App\Models\Book;
use App\Models\Category;
use App\Models\Review;
use Illuminate\Database\Seeder;
use Illuminate\Support\Str;

class CatalogSeeder extends Seeder
{
    /**
     * Seed the curated public-domain catalog.
     *
     * Every title below is a classical or pre-1956 work whose author died at
     * least 70 years ago (or an anonymous classical manuscript), so the work
     * itself is in the public domain in Indonesia. Presentation data (covers,
     * showcase copy, reader previews) is generated by libfree and original.
     *
     * Idempotent: rows are keyed by slug and updated in place. Legacy demo
     * rows that are not part of this audited catalog are unpublished instead
     * of being deleted, so they can still be reviewed in the admin panel.
     */
    public function run(): void
    {
        $categories = [];
        foreach ($this->categories() as $data) {
            $categories[$data['slug']] = Category::updateOrCreate(['slug' => $data['slug']], $data);
        }

        $authors = [];
        foreach ($this->authors() as $data) {
            $authors[$data['slug']] = Author::updateOrCreate(['slug' => $data['slug']], $data);
        }

        $slugs = [];

        foreach ($this->books() as $data) {
            $slugs[] = $data['slug'];
            $author = $authors[$data['author']];
            $category = $categories[$data['category']];

            $data['author_id'] = $author->id;
            $data['category_id'] = $category->id;
            $data['card'] = $this->card($data, $author);
            $data['showcase'] = $this->showcase($data, $author);
            $data['detail'] = null;
            $data['reader_content'] = $this->readerContent($data);
            $data['license_status'] = 'public_domain';
            $data['license_name'] = 'Domain Publik';
            $data['license_url'] = 'https://creativecommons.org/publicdomain/mark/1.0/';
            $data['source_url'] = $this->sourceUrl($data['title']);
            $data['is_published'] = true;
            $data['published_at'] = now();
            $data['audited_at'] = now();

            unset($data['author'], $data['category'], $data['theme']);

            Book::updateOrCreate(['slug' => $data['slug']], $data);
        }

        // Retire legacy demo titles that are not part of the audited catalog.
        Book::query()
            ->whereNotIn('slug', $slugs)
            ->update([
                'is_published' => false,
                'is_featured' => false,
                'is_trending' => false,
                'license_status' => 'unverified',
                'audit_notes' => 'Dinonaktifkan otomatis: tidak termasuk katalog domain publik yang telah diaudit.',
                'audited_at' => now(),
            ]);

        $this->seedReviews();
        $this->syncReviewTotals();
    }

    /**
     * Keep the displayed review count aligned with the rows that actually exist.
     */
    private function syncReviewTotals(): void
    {
        Book::query()
            ->withCount('reviews as reviews_total')
            ->get()
            ->each(function (Book $book) {
                $book->forceFill(['reviews_count' => $book->reviews_total])->save();
            });
    }

