    /**
     * Build the catalog-card presentation payload.
     *
     * @param  array<string, mixed>  $book
     */
    private function card(array $book, Author $author): array
    {
        /** @var array<string, mixed> $theme */
        $theme = $book['theme'];

        return [
            'badge' => $theme['badge'],
            'badge_class' => $theme['badge_class'],
            'cover_class' => $theme['cover_class'],
            'spine_rotate' => 'group-hover:rotate-1',
            'spine_kicker' => $theme['spine_kicker'],
            'spine_kicker_class' => $theme['text_class'],
            'spine_title' => Str::upper($book['title']),
            'spine_title_class' => Str::length($book['title']) > 18 ? 'text-[10px]' : 'text-xs',
            'spine_author' => $author->short_name ?: $author->name,
            'author_label' => $author->name,
            'author_label_class' => $theme['text_class'],
            'formats_label' => collect($book['formats'])->map(fn (string $format) => Str::upper($format))->implode(' • '),
            'related_badge' => $theme['badge'],
            'related_cover_class' => $theme['cover_class'],
            'related_hover_class' => 'group-hover:'.$theme['text_class'],
            'related_button_class' => $theme['button'],
        ];
    }

    /**
     * Build hero, featured, and podium presentation payloads.
     *
     * @param  array<string, mixed>  $book
     */
    private function showcase(array $book, Author $author): ?array
    {
        /** @var array<string, mixed> $theme */
        $theme = $book['theme'];
        $isFeatured = (bool) ($book['is_featured'] ?? false);
        $isPodium = ($book['rank'] ?? 99) <= 3;

        if (! $isFeatured && ! $isPodium) {
            return null;
        }

        $showcase = [];
        $base = [
            'hex' => $theme['hex'],
            'badge' => $theme['badge'],
            'emoji' => $theme['emoji'],
            'title_display' => Str::upper($book['title']),
            'author_display' => $author->short_name ?: $author->name,
            'kicker' => $theme['spine_kicker'],
            'synopsis' => $book['synopsis'],
            'rating_label' => $book['rating'].' ('.$this->compactNumber($book['reviews_count']).')',
        ];

        if ($isFeatured && ($book['featured_rank'] ?? 99) <= 3) {
            $showcase['hero'] = $base + [
                'tags' => [
                    ['label' => $theme['badge'], 'class' => $theme['badge_class']],
                    ['label' => 'Domain Publik', 'class' => 'bg-brand-green-light'],
                ],
                'pages_label' => $book['pages'].' Hlm',
            ];
        }

        if ($isFeatured) {
            $showcase['featured'] = $base + [
                'tag' => ['label' => $theme['badge'], 'class' => $theme['badge_class']],
            ];
        }

        if ($isPodium) {
            $showcase['podium'] = [
                'short' => Str::limit($book['title'], 9, '.'),
                'emoji' => $theme['emoji'],
            ];
        }

        return $showcase;
    }

    /**
     * Original reader preview generated for each title.
     *
     * The catalog does not ship copyrighted manuscripts: these chapters are
     * libfree's own editorial summary, not a reproduction of the source text.
     *
     * @param  array<string, mixed>  $book
     */
    private function readerContent(array $book): array
    {
        $title = $book['title'];
        $synopsis = $book['synopsis'];

        return [
            [
                'title' => 'Bab 1 — Pengantar Arsip',
                'paragraphs' => [
                    $synopsis,
                    'Pratinjau ini disusun oleh tim kurator libfree sebagai pengantar sebelum pembaca membuka edisi lengkap naskah sumber. Ringkasan ini bukan reproduksi teks asli dan tidak menggantikan edisi kritis.',
                    'Setiap karya dalam katalog telah melewati pemeriksaan status hak cipta. Sumber naskah dan dasar lisensinya tercantum pada halaman detail buku.',
                ],
            ],
            [
                'title' => 'Bab 2 — Konteks Penulisan',
                'paragraphs' => [
                    $title.' lahir dari tradisi lisan dan penyalinan naskah yang panjang. Versi yang beredar hari ini sering kali merupakan hasil perbandingan beberapa manuskrip.',
                    'Memahami konteks penulisan membantu pembaca menempatkan gagasan, gaya bahasa, dan nilai-nilai yang terkandung di dalamnya tanpa kehilangan jarak historisnya.',
                    'Catatan kurator pada halaman detail merangkum riwayat penulis, tahun penulisan, serta alasan karya ini berada di domain publik.',
                ],
            ],
            [
                'title' => 'Bab 3 — Panduan Membaca',
                'paragraphs' => [
                    'Pembaca disarankan membaca dengan tempo yang tenang. Banyak istilah klasik memiliki makna yang bergeser; glosarium dan catatan kaki pada edisi lengkap akan membantu.',
                    'Gunakan fitur penanda dan Rak Baca untuk menyimpan bagian yang ingin ditinjau kembali. Progres bacaan tersimpan di perangkat ini.',
                    'Pratinjau berakhir di sini. Naskah lengkap akan tersedia melalui jalur unduhan resmi setelah proses kurasi dan verifikasi berkas selesai.',
                ],
            ],
        ];
    }

