    private function sourceUrl(string $title): string
    {
        return 'https://id.wikisource.org/w/index.php?search='.rawurlencode($title);
    }

    private function compactNumber(int $value): string
    {
        if ($value < 1000) {
            return (string) $value;
        }

        return rtrim(rtrim(number_format($value / 1000, 1, '.', ''), '0'), '.').'k';
    }
